1	package security
2	
3	import (
4		"log"
5	
6		tea "charm.land/bubbletea/v2"
7	
8		"github.com/anthnel/devdesk/internal/clipboard"
9		"github.com/anthnel/devdesk/internal/scan"
10		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
11		"github.com/anthnel/devdesk/internal/ui/shortcut"
12		uiviewer "github.com/anthnel/devdesk/internal/ui/viewer"
13		"github.com/anthnel/devdesk/internal/viewer"
14	)
15	
16	// The finding detail acts (DEVDESK-751). Its keys read the finding on screen
17	// (subjectFinding), never the table row behind it, and each one is decided by an
18	// availability the header and the handler share (Rule 130). DevDesk never runs
19	// the command under Run: Y copies it, and the user runs it.
20	
21	// reasonNoCommand is why Y is greyed: the finding has nothing to copy.
22	const reasonNoCommand = "This finding has no command to run"
23	
24	// writeClipboard is the clipboard write, a variable so a test can take it: the
25	// real one writes to the machine's clipboard. TestMain replaces it.
26	var writeClipboard = clipboard.WriteAll
27	
28	// FixCommandCopiedMsg reports the clipboard write of the command under Run
29	// (Rule 109).
30	type FixCommandCopiedMsg struct {
31		Command string
32		Err     error
33	}
34	
35	// subjectFinding is what a results or details action acts on: the finding on
36	// screen in the details state, the selected row in the results state. A re-scan
37	// puts the table back at the top, so the detail must never read the cursor.
38	func (m Model) subjectFinding() (scan.Finding, bool) {
39		switch m.state {
40		case StateDetails:
41			if m.selectedFinding == nil {
42				return scan.Finding{}, false
43			}
44			return *m.selectedFinding, true
45		case StateResults:
46			return m.findingsTable.Selected()
47		}
48		return scan.Finding{}, false
49	}
50	
51	// canOpenFindingFile says whether enter can open the subject's file. It looks at
52	// the path only: whether the file exists is for the viewer to say.
53	func (m Model) canOpenFindingFile() shortcut.Availability {
54		f, ok := m.subjectFinding()
55		if !ok {
56			return shortcut.Unavailable(reasonNoFinding)
57		}
58		_, a := findingFilePath(f, m.targetPath, m.targetOnDisk())
59		return a
60	}
61	
62	// canCopyFixCommand says whether Y has a command to copy.
63	func (m Model) canCopyFixCommand() shortcut.Availability {
64		f, ok := m.subjectFinding()
65		if !ok {
66			return shortcut.Unavailable(reasonNoFinding)
67		}
68		if _, ok := runCommand(f); !ok {
69			return shortcut.Unavailable(reasonNoCommand)
70		}
71		return shortcut.Availability{}
72	}
73	
74	// openFindingFile asks the router to open the subject's file in the viewer.
75	func (m Model) openFindingFile() (tea.Model, tea.Cmd) {
76		if a := m.canOpenFindingFile(); !a.Enabled() {
77			return m, m.footer.Warn(a.Reason)
78		}
79		f, _ := m.subjectFinding()
80		path, _ := findingFilePath(f, m.targetPath, m.targetOnDisk())
81		return m, func() tea.Msg {
82			return uiviewer.OpenRequestMsg{Source: viewer.NewFileSource(path)}
83		}
84	}
85	
86	// copyFixCommand puts the command under Run on the clipboard, whole. It never
87	// runs it. The command is copied into the Cmd (Rule 110).
88	func (m Model) copyFixCommand() (tea.Model, tea.Cmd) {
89		if a := m.canCopyFixCommand(); !a.Enabled() {
90			return m, m.footer.Warn(a.Reason)
91		}
92		f, _ := m.subjectFinding()
93		command, _ := runCommand(f)
94		return m, func() tea.Msg {
95			return FixCommandCopiedMsg{Command: command, Err: writeClipboard(command)}
96		}
97	}
98	
99	// handleFixCommandCopied reports the clipboard write: a notice on success, an
100	// error without its cause on failure (Rule 128).
101	func (m Model) handleFixCommandCopied(msg FixCommandCopiedMsg) (tea.Model, tea.Cmd) {
102		if msg.Err != nil {
103			log.Printf("ERROR [security] copy command: %v", msg.Err)
104			return m, m.footer.Error("Failed to copy the command — check logs")
105		}
106		return m, m.footer.Info("Command copied to the clipboard")
107	}
108	
109	// refreshDetails rebuilds the detail on the result just put on screen, or closes
110	// it when the finding is gone. It reports whether the detail is still open. The
111	// reason a detail closes is already in the footer: the verdict that brought the
112	// result says the rule is cleared, or still reported.
113	func (m *Model) refreshDetails() bool {
114		if m.state != StateDetails {
115			return false
116		}
117		if m.selectedFinding != nil && m.result != nil {
118			for _, f := range m.result.Findings {
119				if sameFinding(f, *m.selectedFinding) {
120					m.selectedFinding = &f
121					m.detailsViewport.SetContent(m.buildDetailsContent())
122					return true
123				}
124			}
125		}
126		m.state = StateResults
127		m.selectedFinding = nil
128		return false
129	}
130	
131	// verifyingStatus is the footer status while a fix waits on its re-scan: a state
132	// of the screen with the shared activity dot, derived on every frame and gone
133	// with the verdict. Only the target being verified says it.
134	func (m Model) verifyingStatus() (sharedcomponents.Status, bool) {
135		if v := m.misconfigVerifying; v == nil || v.Target != m.targetPath {
136			return sharedcomponents.Status{}, false
137		}
138		return sharedcomponents.Status{Text: "Re-scanning to confirm the fix...", Activity: true}, true
139	}
140

