	for _, f := range result.Findings {
		if scan.Categorize(f) != scan.CategoryMisconfiguration {
			continue
		}
		if f.File == file && remediation.RuleKey(f.ID) == want && (instance == "" || instanceOf(f) == instance) {
			return true
		}
	}
	return false
}

// instanceOf identifies one occurrence of a rule in a file, without its line,
// which the fix itself moves. Trivy words the occurrence in Message ("Container
// 'api' of Deployment 'web' should set…"), kubeconform in Title
// ("Deployment/web: …"); the pair covers both.
func instanceOf(f scan.Finding) string {
	// Scope is what a rule that clears a whole workload is looked for in
	// (DEVDESK-688). The zero value: this occurrence, through holdsRule.
	Scope remediation.Scope
}

// MisconfigVerifiedMsg is the verdict: whether the rule the fix was about is
// still reported for that file.
type MisconfigVerifiedMsg struct {
	Target  string
	Rule    string
	File    string
	Cleared bool
	// Scope is the scope the verdict was judged by; the zero value for a fix of
	// one occurrence.
	Scope remediation.Scope
	// Still lists the rule ids the re-scan still reports in the scope of the
	// fix; Cleared is true when it is empty (DEVDESK-688).
	Still []string
	// Result is the scan the verdict was read from, so the tab can stop showing
	// findings the edit has already dealt with.
	Result *scan.Result
	Err    error
}

// startMisconfigVerification re-scans the target the fix was written into.
//
// It runs even when the catalog is sure of itself, because being sure is not
// the same as having measured — and the cases where a rule survives its own fix
// are exactly the ones nobody predicted.
func (m Model) startMisconfigVerification(v misconfigVerify) tea.Cmd {
	if m.scanningTarget(v.Target) {
		// Something is already measuring this target; its result will answer.
		return nil
	}
	job := inventoryScanJob{Kind: kindRepo, Name: v.Target}
	opts := m.scanOptions()
	return jobs.StartInContext(
		jobs.NewRun(jobs.KindScan, command.ViewSecurity, "", "verify fix", v.Target),
		func(contextName string) tea.Cmd {
			return rescanCmd([]inventoryScanJob{job}, opts, contextName)
		},
	)
}

// verifyMisconfigCmd reads the result the re-scan stored and answers whether the
// rule is still there. It runs off Update (Rule 110).
func verifyMisconfigCmd(v misconfigVerify) tea.Cmd {
	return func() tea.Msg {
		result, err := cache.ReadWorkspaceScanResult(v.Target)
		if err != nil {
			return MisconfigVerifiedMsg{Target: v.Target, Rule: v.Rule, File: v.File, Err: err}
		}
		still := stillReported(result, v)
		return MisconfigVerifiedMsg{
			Target: v.Target, Rule: v.Rule, File: v.File,
			Cleared: len(still) == 0, Still: still, Scope: v.Scope, Result: result,
		}
	}
}

// stillReported lists the rule ids the result still reports for the fix v.
//
// Without a scope it is holdsRule on the occurrence that was fixed. With one, it
// is each rule of the scope looked for in the lines of the edited workload: one
// edit cleared them for every container of the pod, so a finding on another
// container still counts, and a finding of another workload of the file does not.
// A scope with no lines (0, 0: the computation failed) reads the whole file, the
// safe side: "still reported" at worst, never a "fixed" that was not measured.
func stillReported(result *scan.Result, v misconfigVerify) []string {
	if len(v.Scope.Rules) == 0 {
		if holdsRule(result, v.Rule, v.File, v.Instance) {
			return []string{v.Rule}
		}
		return nil
	}
	if result == nil {
		return nil
	}
	var still []string
	for _, rule := range v.Scope.Rules {
		if holdsRuleInScope(result, rule, v.File, v.Scope) {
			still = append(still, rule)
		}
	}
	return still
}

// holdsRuleInScope says whether the result reports rule in file, at a line that
// is inside the scope's lines (anywhere in the file when the scope has none). A
// finding with no line (Line <= 0) cannot be placed outside the scope, so it
// counts as inside: the safe side.

// scanMount is where a scanned directory is mounted inside a scanner container
// (scan.containerScanPath, unexported there).
const scanMount = "/scan"

// pathToken finds an absolute path in a text: it starts at the beginning of the
// text or after a character that cannot be part of a path name, and stops at
// white space or punctuation that ends a path in a message.
var pathToken = REDACTED

// shortPaths rewrites absolute paths inside text for display: "<target>/" and
// the container mount "/scan/" are removed, a bare target becomes ".", and any
// other path under HOME is folded to "~/". target is used only when it is an
// absolute path (an image reference is ignored). Display only: the finding
// keeps its text.
func shortPaths(text, target string) string {
	if text == "" {
		return ""
	}
	root := ""
	if filepath.IsAbs(target) {
		if root = filepath.ToSlash(filepath.Clean(target)); root == "/" {
			root = ""
		}
	}
	return pathToken.ReplaceAllStringFunc(text, func(match string) string {
		at := strings.IndexByte(match, '/')
		path, tail := match[at:], ""
		// A sentence can end on a path: "cannot read /repo."
		if trimmed := strings.TrimRight(path, "."); trimmed != "" {
			path, tail = trimmed, path[len(trimmed):]
		}
		return match[:at] + shortPath(path, root) + tail
	})
}

// shortPath shortens one absolute path: relative to the target, relative to the
// container mount, or folded under HOME.
func shortPath(path, root string) string {
	for _, base := range []string{root, scanMount} {
		switch {
		case base == "":
		case path == base:
			return "."
		case strings.HasPrefix(path, base+"/"):
			if rest := strings.TrimLeft(path[len(base):], "/"); rest != "" {
				return rest
			}
			return "."
		}
	}
	return theme.FoldHome(path)
}

// oneLine is the first line of text, cut to width cells with theme.Ellipsis.
// It measures with x/ansi, as the viewport does, not with runewidth, after the
// tabs and carriage returns are gone: x/ansi counts a tab as no cell while the
// renderer lays it out as four spaces.
func oneLine(text string, width int) string {
	if width <= 0 {
		return ""
	}
	first, _, _ := strings.Cut(text, "\n")
	first = withoutControlSpace(first)
	if ansi.StringWidth(first) <= width {
		return first
	}
	return ansi.Truncate(first, width, theme.Ellipsis)
}

// cappedLines wraps text at min(width, maxMessageWidth), hard-breaking a token
// longer than that, and keeps the first maxLines lines. hidden counts the wrapped
// lines left out. A blank text gives nil, 0.
func cappedLines(text string, width, maxLines int) (lines []string, hidden int) {
	if strings.TrimSpace(text) == "" {
		return nil, 0
	}
	text = strings.TrimRight(text, " \t\r\n")
	lines = strings.Split(ansi.Wrap(text, max(min(width, maxMessageWidth), 1), ""), "\n")
	if len(lines) > maxLines {
		return lines[:maxLines], len(lines) - maxLines
	}
	return lines, 0
}

// moreLines is the marker after a capped text, "" when nothing was left out.
func moreLines(n int) string {
	switch {
	case n <= 0:
		return ""
	case n == 1:
		return "… 1 more line"
	}
	return fmt.Sprintf("… %d more lines", n)
}

// scrollPosition is "Lines a-b of N" when the content is taller than the
// viewport, "" otherwise.
func scrollPosition(offset, visible, total int) string {
	if visible <= 0 || total <= visible {
		return ""
	}
	offset = max(offset, 0)
	return fmt.Sprintf("Lines %d-%d of %d", offset+1, min(offset+visible, total), total)
}

// withoutControlSpace drops carriage returns and turns a tab into four spaces,
// which is how the renderer lays it out.
func withoutControlSpace(text string) string {
	return strings.ReplaceAll(strings.ReplaceAll(text, "\r", ""), "\t", "    ")
}

// normalizeText makes a scanner's text safe to lay out: a tab or a carriage
// return has no width the viewport and the terminal agree on, trailing spaces
// are noise, and a run of blank lines is one blank line. dropBlank removes the
// blank lines altogether (a stderr, where they separate nothing).
func normalizeText(text string, dropBlank bool) string {
	text = withoutControlSpace(text)
	var out []string
	for _, line := range strings.Split(text, "\n") {
		line = strings.TrimRight(line, " ")
		blank := line == ""
		switch {
		case blank && (dropBlank || len(out) == 0 || out[len(out)-1] == ""):
		default:
			out = append(out, line)
		}
	}
	for len(out) > 0 && out[len(out)-1] == "" {
		out = out[:len(out)-1]
	}
	return strings.Join(out, "\n")
}

// dropBlankLines is normalizeText without any blank line.
func dropBlankLines(text string) string { return normalizeText(text, true) }

// detailsText lays text out for the finding detail: every line it returns is
// styled on the theme background and spans at most width cells, measured with
// x/ansi as the viewport does.
type detailsText struct {
	width int            // cells a line may span
	text  lipgloss.Style // ordinary text
	dim   lipgloss.Style // secondary text
}

func newDetailsText(width int) detailsText {
	return detailsText{
		width: width,
		text:  lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText),
		dim:   theme.DimStyle,
	}
}

// block wraps text at the full width, one styled line per entry.
func (t detailsText) block(text string, style lipgloss.Style) []string {
	return t.indented("", text, style)
}

// indented wraps text under a prefix of spaces.
func (t detailsText) indented(prefix, text string, style lipgloss.Style) []string {
	text = normalizeText(text, false)
	if text == "" {
		return nil
	}
	var lines []string
	for _, line := range t.wrapped(text, t.width-ansi.StringWidth(prefix)) {
		if line == "" {
			lines = append(lines, "")
			continue
		}
		lines = append(lines, margin(ansi.StringWidth(prefix))+style.Render(line))
	}
	return lines
}

